        {
            return true;
        }

        m = 31 * 37 * 41 * 43 * 47;
        r = BigIntegers.intValueExact(x.mod(BigInteger.valueOf(m)));
        if ((r % 31) < 2 || (r % 37) < 2 || (r % 41) < 2 || (r % 43) < 2 || (r % 47) < 2)
        {
            return true;
        }

        m = 53 * 59 * 61 * 67 * 71;
        r = BigIntegers.intValueExact(x.mod(BigInteger.valueOf(m)));
        if ((r % 53) < 2 || (r % 59) < 2 || (r % 61) < 2 || (r % 67) < 2 || (r % 71) < 2)
